create extension if not exists pgcrypto;
create type public.member_role as enum('owner','admin','editor','viewer');
create table public.workspaces(id uuid primary key default gen_random_uuid(),name text not null,owner_id uuid not null references auth.users(id),created_at timestamptz default now());
create table public.workspace_members(workspace_id uuid references public.workspaces(id) on delete cascade,user_id uuid references auth.users(id) on delete cascade,role public.member_role not null,primary key(workspace_id,user_id));
create table public.workspace_invitations(id uuid primary key default gen_random_uuid(),workspace_id uuid references public.workspaces(id) on delete cascade,email text not null,role public.member_role not null,status text not null default 'pending' check(status in('pending','accepted','revoked')),invited_by uuid references auth.users(id),created_at timestamptz default now(),unique(workspace_id,email));
create table public.payments(id uuid primary key default gen_random_uuid(),workspace_id uuid not null references public.workspaces(id) on delete cascade,created_by uuid not null references auth.users(id),vendor text not null,payment_date date not null,mode text not null,purpose text not null,amount numeric(14,2) not null check(amount>=0),created_at timestamptz default now());
alter table public.workspaces enable row level security;alter table public.workspace_members enable row level security;alter table public.workspace_invitations enable row level security;alter table public.payments enable row level security;
create function public.is_member(w uuid) returns boolean language sql stable security definer set search_path=public as $$select exists(select 1 from workspace_members where workspace_id=w and user_id=auth.uid())$$;
create function public.has_role(w uuid,roles public.member_role[]) returns boolean language sql stable security definer set search_path=public as $$select exists(select 1 from workspace_members where workspace_id=w and user_id=auth.uid() and role=any(roles))$$;
create policy p_read on payments for select using(is_member(workspace_id));create policy p_write on payments for insert with check(has_role(workspace_id,array['owner','admin','editor']::member_role[]) and created_by=auth.uid());create policy p_update on payments for update using(has_role(workspace_id,array['owner','admin','editor']::member_role[]));create policy p_delete on payments for delete using(has_role(workspace_id,array['owner','admin','editor']::member_role[]));
create function public.create_workspace(p_name text) returns uuid language plpgsql security definer set search_path=public as $$declare w uuid;begin if exists(select 1 from workspace_members where user_id=auth.uid()) then raise exception 'User already has a workspace';end if;insert into workspaces(name,owner_id)values(trim(p_name),auth.uid())returning id into w;insert into workspace_members values(w,auth.uid(),'owner');return w;end$$;
create function public.my_workspace() returns jsonb language sql stable security definer set search_path=public as $$select jsonb_build_object('workspace_id',w.id,'workspace_name',w.name,'role',m.role) from workspace_members m join workspaces w on w.id=m.workspace_id where m.user_id=auth.uid() limit 1$$;
create function public.invite_workspace_user(p_email text,p_role member_role) returns uuid language plpgsql security definer set search_path=public as $$declare w uuid;i uuid;begin select workspace_id into w from workspace_members where user_id=auth.uid() and role in('owner','admin') limit 1;if w is null or p_role='owner' then raise exception 'Not authorized';end if;insert into workspace_invitations(workspace_id,email,role,invited_by)values(w,lower(trim(p_email)),p_role,auth.uid())on conflict(workspace_id,email)do update set role=excluded.role,status='pending',invited_by=auth.uid(),created_at=now() returning id into i;return i;end$$;
create function public.my_pending_invitations() returns jsonb language sql stable security definer set search_path=public as $$select coalesce(jsonb_agg(jsonb_build_object('id',i.id,'workspace_name',w.name,'role',i.role)),'[]') from workspace_invitations i join workspaces w on w.id=i.workspace_id where i.email=lower(auth.jwt()->>'email') and i.status='pending'$$;
create function public.accept_invitation(p_invitation uuid) returns void language plpgsql security definer set search_path=public as $$declare i workspace_invitations;begin select * into i from workspace_invitations where id=p_invitation and email=lower(auth.jwt()->>'email') and status='pending' for update;if not found then raise exception 'Invitation not found';end if;if exists(select 1 from workspace_members where user_id=auth.uid())then raise exception 'User already belongs to a workspace';end if;insert into workspace_members values(i.workspace_id,auth.uid(),i.role);update workspace_invitations set status='accepted' where id=i.id;end$$;
create function public.admin_access_list() returns jsonb language plpgsql security definer set search_path=public as $$declare w uuid;begin select workspace_id into w from workspace_members where user_id=auth.uid() and role in('owner','admin') limit 1;if w is null then raise exception 'Not authorized';end if;return jsonb_build_object('members',(select coalesce(jsonb_agg(jsonb_build_object('user_id',m.user_id,'email',u.email,'role',m.role)),'[]') from workspace_members m join auth.users u on u.id=m.user_id where m.workspace_id=w),'invitations',(select coalesce(jsonb_agg(to_jsonb(i)),'[]') from workspace_invitations i where i.workspace_id=w));end$$;
create function public.change_member_role(p_user uuid,p_role member_role) returns void language plpgsql security definer set search_path=public as $$declare w uuid;begin select workspace_id into w from workspace_members where user_id=auth.uid() and role in('owner','admin') limit 1;if p_role='owner' then raise exception 'Owner role cannot be assigned';end if;update workspace_members set role=p_role where workspace_id=w and user_id=p_user and role<>'owner';end$$;
create function public.remove_workspace_member(p_user uuid) returns void language plpgsql security definer set search_path=public as $$declare w uuid;begin select workspace_id into w from workspace_members where user_id=auth.uid() and role in('owner','admin') limit 1;delete from workspace_members where workspace_id=w and user_id=p_user and role<>'owner';end$$;
create function public.revoke_invitation(p_invitation uuid) returns void language plpgsql security definer set search_path=public as $$declare w uuid;begin select workspace_id into w from workspace_members where user_id=auth.uid() and role in('owner','admin') limit 1;update workspace_invitations set status='revoked' where id=p_invitation and workspace_id=w;end$$;
revoke all on function public.admin_access_list() from public;grant execute on function public.admin_access_list() to authenticated;
